def two(en, fr): return {"en": en, "fr": fr}


M = lambda mission, chap, en, fr: [mission, chap, two(en, fr)]
K = lambda name, game, mission, en, fr: [name, game, mission, two(en, fr)]

C1 = two("1. Colter", "1. Colter")
